package com.shatteredpixel.shatteredpixeldungeon.apd.query.research;
import com.shatteredpixel.shatteredpixeldungeon.apd.query.*;
import com.shatteredpixel.shatteredpixeldungeon.apd.stats.Fact;
import org.junit.Test;
import static org.junit.Assert.*;
public class PopulationStudyTest {
    private PopulationStudy.Sample sample(ResearchFixture f,Query q){return PopulationStudy.sample(f.result(q),"result.score");}
    @Test public void meansMediansVarianceAndExclusionsUseExactContributors(){ResearchFixture f=new ResearchFixture();f.add("a","mage",0,10);f.add("b","mage",0,30);Row unknown=f.add("c","mage",0,999);unknown.clear(f.def.indexOf("result.score"));Row partial=f.add("d","mage",0,999);partial.setNum(f.def.indexOf("result.score"),999,Fact.PROV_INCOMPLETE);PopulationStudy.Sample s=sample(f,f.query());assertEquals(2,s.n);assertEquals(2,s.excluded);assertEquals(20,s.mean,0);assertEquals(20,s.median,0);assertEquals(Math.sqrt(200),s.sd,1e-12);}
    @Test public void independentMatchedSamplesGetAnInterval(){ResearchFixture f=new ResearchFixture();for(int i=0;i<20;i++){f.add("a"+i,"mage",0,10+i);f.add("b"+i,"warrior",0,30+i);}PopulationStudy.Comparison c=PopulationStudy.compare(sample(f,f.forClass("mage")),sample(f,f.forClass("warrior")));assertTrue(c.intervalKnown);assertEquals(-20,c.difference,1e-12);assertTrue(c.low<-20 && c.high>-20);}
    @Test public void overlapAndVersionDifferencesSuppressInference(){ResearchFixture f=new ResearchFixture();for(int i=0;i<40;i++)f.add("a"+i,"mage",0,i);PopulationStudy.Comparison overlap=PopulationStudy.compare(sample(f,f.query()),sample(f,f.query()));assertEquals(40,overlap.overlappingRuns);assertFalse(overlap.intervalKnown);for(int i=20;i<40;i++){f.text(f.rows.get(i),"run.heroClass","warrior");f.text(f.rows.get(i),"run.apdVersion","v2");}assertFalse(PopulationStudy.compare(sample(f,f.forClass("mage")),sample(f,f.forClass("warrior"))).intervalKnown);}
    @Test public void winRateKeepsAbandonmentAsANonWinAndUsesNondegenerateWilsonBounds(){ResearchFixture f=new ResearchFixture();for(int i=0;i<20;i++){f.add("a"+i,"mage",1,0);f.add("b"+i,"warrior",i%2==0?0:2,0);}PopulationStudy.Comparison c=PopulationStudy.compare(PopulationStudy.sample(f.result(f.forClass("mage")),PopulationStudy.WIN_RATE),PopulationStudy.sample(f.result(f.forClass("warrior")),PopulationStudy.WIN_RATE));assertTrue(c.intervalKnown);assertEquals(100,c.difference,0);assertTrue(c.low<100 && c.low>0);assertEquals(100,c.high,1e-12);}
    @Test public void unknownOutcomesAndUnfinishedRunsNeverBecomeLosses(){ResearchFixture f=new ResearchFixture();f.add("win","mage",1,0);Row unknown=f.add("unknown","mage",0,0);unknown.clear(f.def.indexOf("result.outcome"));f.add("live","mage",0,0).finished=false;PopulationStudy.Sample s=PopulationStudy.sample(f.result(),PopulationStudy.WIN_RATE);assertEquals(1,s.n);assertEquals(100,s.mean,0);assertEquals(2,s.excluded);}
    @Test public void emptySmallAndInvalidQueriesFailHonestly(){ResearchFixture f=new ResearchFixture();PopulationStudy.Sample s=sample(f,f.query());assertEquals(0,s.n);assertTrue(Double.isNaN(s.mean));assertNull(PopulationStudy.sample(f.result(),"missing"));assertNull(PopulationStudy.sample(f.result(),"result.outcome"));assertNull(ResearchData.select(f.catalog(),f.query().addFilter(Filter.num("removed",Op.GT,2)),"rules"));}
    @Test public void evidenceNavigationRetainsBackAndRejectsUnsupportedStoredFilters(){ResearchFixture f=new ResearchFixture();f.add("a","mage",0,10);UimsdModel m=new UimsdModel("rules","Rules");m.setCatalog(f.catalog());Query original=m.query();assertTrue(m.openResearchQuery(f.forClass("mage")));assertTrue(m.canGoBack());m.back();assertEquals(original,m.query());assertFalse(m.openResearchQuery(f.query().addFilter(Filter.num("removed",Op.EQ,3))));assertEquals(original,m.query());}
}
